import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines = new ArrayList<>();
        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = br.readLine()) != null) {
            lines.add(line);
        }
        br.close();

        Pattern pattern = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2}) (\\d{2}):(\\d{2}):(\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)$");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrors = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        for (String l : lines) {
            Matcher m = pattern.matcher(l.trim());
            if (m.matches()) {
                String hour = m.group(2);
                String level = m.group(5);
                String component = m.group(6);
                String message = m.group(7);

                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                if (level.equalsIgnoreCase("ERROR")) {
                    componentErrors.put(component, componentErrors.getOrDefault(component, 0) + 1);
                    errorMessages.add(message);
                }

                hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);
            }
        }

        String topComponent = "";
        int topCount = 0;
        for (Map.Entry<String, Integer> e : componentErrors.entrySet()) {
            if (e.getValue() > topCount) {
                topCount = e.getValue();
                topComponent = e.getKey();
            }
        }

        String topHour = "00";
        int topHourCount = 0;
        for (Map.Entry<String, Integer> e : hourCounts.entrySet()) {
            if (e.getValue() > topHourCount) {
                topHourCount = e.getValue();
                topHour = e.getKey();
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> e : levelCounts.entrySet()) {
            sb.append("  ").append(e.getKey()).append(": ").append(e.getValue()).append("\n");
        }
        sb.append("\n");
        sb.append("Component with Most Errors: ").append(topComponent).append(" (").append(topCount).append(" errors)\n");
        sb.append("\n");
        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");
        sb.append("Busiest Hour: ").append(topHour).append(":00 (").append(topHourCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

