import * as fs from 'fs';

const pathA = '<tmp>';
const pathB = '<tmp>';

const a: any = JSON.parse(fs.readFileSync(pathA, 'utf-8'));
const b: any = JSON.parse(fs.readFileSync(pathB, 'utf-8'));

function isObject(val: any): boolean {
  return val !== null && typeof val === 'object' && !Array.isArray(val);
}

function deepMerge(aVal: any, bVal: any): any {
  if (isObject(aVal) && isObject(bVal)) {
    const result: any = {};
    const keys = new Set<string>([...Object.keys(aVal), ...Object.keys(bVal)]);
    for (const key of keys) {
      if (key in aVal && key in bVal) {
        result[key] = deepMerge(aVal[key], bVal[key]);
      } else if (key in aVal) {
        result[key] = aVal[key];
      } else {
        result[key] = bVal[key];
      }
    }
    return result;
  }
  if (Array.isArray(aVal) && Array.isArray(bVal)) {
    const seen = new Set<string>();
    const result: any[] = [];
    for (const item of aVal) {
      const key = JSON.stringify(item);
      if (!seen.has(key)) {
        seen.add(key);
        result.push(item);
      }
    }
    for (const item of bVal) {
      const key = JSON.stringify(item);
      if (!seen.has(key)) {
        seen.add(key);
        result.push(item);
      }
    }
    return result;
  }
  return bVal;
}

function sortKeys(val: any): any {
  if (Array.isArray(val)) {
    return val.map(sortKeys);
  }
  if (isObject(val)) {
    const sorted: any = {};
    const keys = Object.keys(val).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(val[key]);
    }
    return sorted;
  }
  return val;
}

