import Foundation

func formatWithCommas(_ number: Int) -> String {
    let isNegative = number < 0
    let absNum = abs(number)
    let str = String(absNum)
    var result = ""
    let chars = Array(str)
    for (i, c) in chars.enumerated() {
        if i > 0 && (chars.count - i) % 3 == 0 {
            result += ","
        }
        result.append(c)
    }
    return (isNegative ? "-" : "") + result
}

func formatWithCommasAndDecimals(_ number: Double, decimals: Int = 2) -> String {
    let formatted = String(format: "%.\(decimals)f", number)
    let parts = formatted.split(separator: ".", maxSplits: 1)
    let intPart = String(parts[0])
    let decPart = parts.count > 1 ? String(parts[1]) : ""
    let intFormatted = formatWithCommas(Int(intPart)!)
    return decPart.isEmpty ? intFormatted : "\(intFormatted).\(decPart)"
}

let filePath = "<tmp>"
let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }

var departments: [String: [Double]] = [:]
var totalBudget = 0.0
var maxSalary = -1.0
var maxName = ""

for (i, line) in lines.enumerated() {
    if i == 0 { continue }
    let fields = line.components(separatedBy: ",").map { $0.trimmingCharacters(in: .whitespaces) }
    guard fields.count >= 6 else { continue }
    let name = fields[1]
    let dept = fields[2]
    let salary = Double(fields[3]) ?? 0.0

    departments[dept, default: []].append(salary)
    totalBudget += salary

    if salary > maxSalary {
        maxSalary = salary
        maxName = name
    }
}

print("=== Salary Report ===")
print()
print("Average Salary by Department:")
