#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char name[256];
    char department[256];
    double salary;
} Employee;

typedef struct {
    char name[256];
    double total;
    int count;
} DeptAgg;

static int cmp_depts(const void *a, const void *b) {
    const DeptAgg *da = (const DeptAgg *)a;
    const DeptAgg *db = (const DeptAgg *)b;
    return strcmp(da->name, db->name);
}

static void fmt_comma_int(long val, char *buf, size_t bufsz) {
    char tmp[64];
    int neg = 0;
    if (val < 0) { neg = 1; val = -val; }
    snprintf(tmp, sizeof(tmp), "%ld", val);
    int len = (int)strlen(tmp);
    int pos = 0;
    if (neg) buf[pos++] = '-';
    for (int i = 0; i < len; i++) {
        buf[pos++] = tmp[i];
        int remaining = len - i - 1;
        if (remaining > 0 && remaining % 3 == 0)
            buf[pos++] = ',';
    }
    buf[pos] = '\0';
}

static void fmt_comma_double(double val, char *buf, size_t bufsz) {
    char tmp[64];
    snprintf(tmp, sizeof(tmp), "%.2f", val);
    int neg = 0;
    if (tmp[0] == '-') { neg = 1; tmp[0] = '\0'; }
    /* split integer and fractional */
    char *dot = strchr(tmp, '.');
    int ilen = (int)(dot - tmp);
    int pos = 0;
    if (neg) buf[pos++] = '-';
    for (int i = 0; i < ilen; i++) {
        buf[pos++] = tmp[i];
        int remaining = ilen - i - 1;
        if (remaining > 0 && remaining % 3 == 0)
            buf[pos++] = ',';
    }
    /* fractional part */
    if (dot) {
        buf[pos++] = '.';
        buf[pos++] = dot[1];
        buf[pos++] = dot[2];
    }
    buf[pos] = '\0';
}

int main(void) {
    const char *path = "<tmp>";
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s\n", path);
        return 1;
    }

    size_t cap = 1024;
    Employee *emps = (Employee *)malloc(cap * sizeof(Employee));
    int n = 0;

    char *line = (char *)malloc(8192);
    int first = 1;

    while (fgets(line, 8192, fp)) {
        /* strip trailing newline */
        size_t ll = strlen(line);
        while (ll > 0 && (line[ll-1] == '\n' || line[ll-1] == '\r'))
            line[--ll] = '\0';
        if (ll == 0) continue;

        if (first) { first = 0; continue; } /* skip header */

        if (n >= (int)cap) {
            cap *= 2;
            emps = (Employee *)realloc(emps, cap * sizeof(Employee));
        }

        /* parse: employee_id, name, department, salary, start_date, rating */
        char *fields[6];
        int nf = 0;
        char *p = line;
        for (int i = 0; i < 6; i++) {
            fields[i] = p;
            while (*p && *p != ',') p++;
            if (*p == ',') { *p = '\0'; p++; }
            else break;
            nf++;
        }
        /* if fewer than 6 fields, pad */
        while (nf < 6) { fields[nf++] = ""; }

        strncpy(emps[n].name, fields[1], 255);
        emps[n].name[255] = '\0';
        strncpy(emps[n].department, fields[2], 255);
        emps[n].department[255] = '\0';
        emps[n].salary = atof(fields[3]);
        n++;
    }
    free(line);
    fclose(fp);

    /* Aggregate by department */
    int dcap = 64;
    DeptAgg *depts = (DeptAgg *)malloc(dcap * sizeof(DeptAgg));
    int nd = 0;

    for (int i = 0; i < n; i++) {
        int found = -1;
        for (int j = 0; j < nd; j++) {
            if (strcmp(depts[j].name, emps[i].department) == 0) { found = j; break; }
        }
        if (found < 0) {
            if (nd >= dcap) { dcap *= 2; depts = (DeptAgg *)realloc(depts, dcap * sizeof(DeptAgg)); }
            strncpy(depts[nd].name, emps[i].department, 255);
            depts[nd].name[255] = '\0';
            depts[nd].total = 0;
            depts[nd].count = 0;
            found = nd++;
        }
        depts[found].total += emps[i].salary;
        depts[found].count++;
    }

    qsort(depts, nd, sizeof(DeptAgg), cmp_depts);

    /* Find highest paid */
    int hi = 0;
    for (int i = 1; i < n; i++) {
        if (emps[i].salary > emps[hi].salary) hi = i;
    }

    /* Total budget */
    double total = 0;
    for (int i = 0; i < n; i++) total += emps[i].salary;

    /* Output */
    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < nd; i++) {
        double avg = depts[i].total / depts[i].count;
        char buf[128];
        fmt_comma_double(avg, buf, sizeof(buf));
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");
    {
        char buf[128];
        fmt_comma_int((long)emps[hi].salary, buf, sizeof(buf));
        printf("Highest Paid: %s ($%s)\n", emps[hi].name, buf);
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < nd; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    {
        char buf[128];
        fmt_comma_int((long)total, buf, sizeof(buf));
        printf("Total Budget: $%s\n", buf);
    }

    free(emps);
    free(depts);
    return 0;
}

