fn format_int_with_commas(n: i64) -> String {
    let neg = n < 0;
    let abs = if neg { -n } else { n };
    let s = abs.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if neg {
        result.insert(0, '-');
    }
    result
}

fn format_money(value: f64, decimals: usize) -> String {
    if decimals == 0 {
        let int_val = value.round() as i64;
        format!("${}", format_int_with_commas(int_val))
    } else {
        let multiplier = 100_f64.powi(decimals as i32);
        let scaled = (value * multiplier).round() as i64;
        let int_part = scaled / multiplier as i64;
        let dec_part = (scaled % multiplier as i64).abs();
        let int_str = format_int_with_commas(int_part);
        let dec_str = format!("{:0width$}", dec_part, width = decimals);
        format!("${}.{}", int_str, dec_str)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_name = String::new();
    let mut highest_salary = f64::MIN;
    let mut total_budget = 0.0_f64;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|s| s.trim()).collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }

        total_budget += salary;
    }

    let mut depts: Vec<&String> = dept_salaries.keys().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let salaries = &dept_salaries[*dept];
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: {}", dept, format_money(avg, 2));
    }
    println!();
    println!("Highest Paid: {} ({})", highest_name, format_money(highest_salary, 0));
    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let count = dept_salaries[*dept].len();
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: {}", format_money(total_budget, 0));
}

