import * as http from 'http';

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

const options: http.RequestOptions = {
  hostname: '127.0.0.1',
  port: 18923,
  path: '/api/products',
  method: 'GET',
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk: string) => {
    data += chunk;
  });
  res.on('end', () => {
    const products: Product[] = JSON.parse(data);
    const filtered = products.filter((p) => p.price > 50.0);
    filtered.sort((a, b) => a.name.localeCompare(b.name));

    const lines: string[] = [];
    lines.push('=== Filtered Products (price > $50.00) ===');
    lines.push('');
    for (const p of filtered) {
      lines.push(`${p.name}: $${p.price.toFixed(2)}`);
    }
    lines.push('');
    lines.push(`Count: ${filtered.length}`);
    const total = filtered.reduce((sum, p) => sum + p.price, 0);
    lines.push(`Total: $${total.toFixed(2)}`);

    process.stdout.write(lines.join('\n') + '\n');
  });
});

req.on('error', (err) => {
  process.stderr.write(err.message + '\n');
  process.exit(1);
});

req.end();

