use std::collections::{BTreeMap, BTreeSet};
use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<String, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Find closing bracket of timestamp
        let close_bracket = match line.find(']') {
            Some(pos) => pos,
            None => continue,
        };

        // Timestamp is between [ and ]: "YYYY-MM-DD HH:MM:SS"
        let ts = &line[1..close_bracket];
        // Hour is at positions 11..13 of "YYYY-MM-DD HH:MM:SS"
        let hour = &ts[11..13];
        let hour_key = format!("{}:00", hour);
        *hour_counts.entry(hour_key).or_insert(0) += 1;

        // After ']', trim to get "LEVEL (component) - message"
        let rest = line[close_bracket + 1..].trim_start();

        // Find '(' for component
        let open_paren = match rest.find('(') {
            Some(pos) => pos,
            None => continue,
        };
        let level = rest[..open_paren].trim().to_string();

        // Find ')' for component end
        let close_paren = match rest[open_paren..].find(')') {
            Some(pos) => open_paren + pos,
            None => continue,
        };
        let component = rest[open_paren + 1..close_paren].to_string();

        // After ')', we have " - message"
        let after_paren = &rest[close_paren + 1..];
        let message = after_paren
            .trim_start()
            .strip_prefix('-')
            .unwrap_or(after_paren.trim_start())
            .trim_start()
            .to_string();

        *level_counts.entry(level.clone()).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component.clone()).or_insert(0) += 1;
            error_messages.insert(message);
        }
    }

    print!("=== Log Analysis ===\n");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();
    if !error_component_counts.is_empty() {
        let (top_comp, top_count) = error_component_counts
            .iter()
            .max_by_key(|(_, c)| *c)
            .unwrap();
        println!("Component with Most Errors: {} ({} errors)", top_comp, top_count);
    } else {
        println!("Component with Most Errors: N/A (0 errors)");
    }
    println!();
    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();
    if !hour_counts.is_empty() {
        let (top_hour, top_count) = hour_counts
            .iter()
            .max_by_key(|(_, c)| *c)
            .unwrap();
        println!("Busiest Hour: {} ({} entries)", top_hour, top_count);
    } else {
        println!("Busiest Hour: 00:00 (0 entries)");
    }
}

