let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    guard line.hasPrefix("["), let closeBracket = line.firstIndex(of: "]") else { continue }

    let timestamp = String(line[line.index(after: line.startIndex)..<closeBracket])
    let tsParts = timestamp.components(separatedBy: " ")
    if tsParts.count >= 2 {
        let timeParts = tsParts[1].components(separatedBy: ":")
        if timeParts.count >= 1, let hour = Int(timeParts[0]) {
            hourCounts[hour, default: 0] += 1
        }
    }

    let rest = String(line[line.index(after: closeBracket)...]).trimmingCharacters(in: .whitespaces)

    guard let openParen = rest.firstIndex(of: "(") else { continue }
    guard let closeParen = rest.firstIndex(of: ")") else { continue }

    let level = String(rest[..<openParen]).trimmingCharacters(in: .whitespaces)
    let component = String(rest[rest.index(after: openParen)..<closeParen])

    let afterComponent = String(rest[rest.index(after: closeParen)...])
    var message = afterComponent
    if message.hasPrefix(" - ") {
        message = String(message.dropFirst(3))
    } else if message.hasPrefix(" -") {
        message = String(message.dropFirst(2)).trimmingCharacters(in: .whitespaces)
    } else {
        message = message.trimmingCharacters(in: .whitespaces)
    }

    levelCounts[level, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

