            if (obj.charAt(idx) == '"') break;
            idx++;
        }
        return obj.substring(start, idx);
    }

    static double extractNumber(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        if (idx == -1) return 0;
        idx += search.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == '\t' || obj.charAt(idx) == '\n' || obj.charAt(idx) == '\r')) idx++;
        int start = idx;
        while (idx < obj.length() && (Character.isDigit(obj.charAt(idx)) || obj.charAt(idx) == '.' || obj.charAt(idx) == '-' || obj.charAt(idx) == '+' || obj.charAt(idx) == 'e' || obj.charAt(idx) == 'E')) {
            idx++;
        }
        String numStr = obj.substring(start, idx);
        if (numStr.isEmpty()) return 0;
        return Double.parseDouble(numStr);
    }
