import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath: string = '<tmp>';
    const data: string = fs.readFileSync(filePath, 'utf-8');
    const graph: Graph = JSON.parse(data);

    const nodes: string[] = graph.nodes;
    const edges: Edge[] = graph.edges;

    // Build adjacency list (undirected)
    const adj: Map<string, { to: string; weight: number }[]> = new Map();
    for (const node of nodes) {
        adj.set(node, []);
    }
    for (const edge of edges) {
        adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
    }

    // Dijkstra's algorithm from node "A"
    const dist: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of nodes) {
        dist.set(node, Infinity);
    }
    dist.set('A', 0);

    for (let i = 0; i < nodes.length; i++) {
        let minNode: string | null = null;
        let minDist: number = Infinity;
        for (const node of nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                minNode = node;
            }
        }

        if (minNode === null) break;

        visited.add(minNode);

        const neighbors = adj.get(minNode)!;
        for (const neighbor of neighbors) {
            if (!visited.has(neighbor.to)) {
                const newDist: number = dist.get(minNode)! + neighbor.weight;
                if (newDist < dist.get(neighbor.to)!) {
                    dist.set(neighbor.to, newDist);
                }
            }
        }
    }

    // Output
    const lines: string[] = [];
    lines.push('=== Shortest Paths from A ===');
    lines.push('');

    const sorted: string[] = [...nodes].sort();
    for (const node of sorted) {
        const d: number = dist.get(node)!;
        lines.push(`A -> ${node}: ${d}`);
    }

    process.stdout.write(lines.join('\n') + '\n');
}

main();

