import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class Main {
    public static void main(String[] args) throws Exception {
        String a = new String(Files.readAllBytes(
                Path.of("<tmp>")),
                StandardCharsets.UTF_8);
        String b = new String(Files.readAllBytes(
                Path.of("<tmp>")),
                StandardCharsets.UTF_8);

        Object ma = new JsonParser(a).parse();
        Object mb = new JsonParser(b).parse();
        Object merged = merge(ma, mb);
        System.out.println(pretty(merged, 0));
    }

    static Object merge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> ra = (Map<String, Object>) a;
            @SuppressWarnings("unchecked")
            Map<String, Object> rb = (Map<String, Object>) b;
            Map<String, Object> r = new LinkedHashMap<>();
            Set<String> keys = new LinkedHashSet<>(ra.keySet());
            keys.addAll(rb.keySet());
            for (String k : keys) {
                if (ra.containsKey(k) && rb.containsKey(k)) {
                    r.put(k, merge(ra.get(k), rb.get(k)));
                } else {
                    r.put(k, ra.containsKey(k) ? ra.get(k) : rb.get(k));
                }
            }
            return r;
        }
        if (a instanceof List && b instanceof List) {
            List<?> la = (List<?>) a;
            List<?> lb = (List<?>) b;
            List<Object> r = new ArrayList<>(la);
            Set<String> seen = new LinkedHashSet<>();
            for (Object o : la) seen.add(canonical(o));
            for (Object o : lb) {
                if (seen.add(canonical(o))) r.add(o);
            }
            return r;
        }
        // Scalar conflict or type mismatch: B overrides A
        return b;
    }

    static String fmtDouble(double d) {
        if (Double.isFinite(d) && d == Math.rint(d) && Math.abs(d) < 1e15) {
            return Long.toString((long) d) + ".0";
        }
        return Double.toString(d);
    }

    static String quote(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        return sb.append('"').toString();
    }

    static String pad(int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append("  ");
        return sb.toString();
    }

    static String pretty(Object v, int indent) {
        if (v == null) return "null";
        if (v instanceof Boolean || v instanceof Long) return v.toString();
        if (v instanceof Double) return fmtDouble((Double) v);
        if (v instanceof String) return quote((String) v);
        if (v instanceof List) {
            List<?> list = (List<?>) v;
            if (list.isEmpty()) return "[]";
            StringBuilder sb = new StringBuilder("[\n");
            String pad = pad(indent + 1);
            for (int i = 0; i < list.size(); i++) {
                sb.append(pad).append(pretty(list.get(i), indent + 1));
                if (i < list.size() - 1) sb.append(',');
                sb.append('\n');
            }
            sb.append(pad(indent)).append(']');
            return sb.toString();
        }
        if (v instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> map = (Map<String, Object>) v;
            if (map.isEmpty()) return "{}";
            List<String> keys = new ArrayList<>(map.keySet());
            Collections.sort(keys);
            StringBuilder sb = new StringBuilder("{\n");
            String pad = pad(indent + 1);
            for (int i = 0; i < keys.size(); i++) {
                sb.append(pad).append(quote(keys.get(i))).append(": ")
                  .append(pretty(map.get(keys.get(i)), indent + 1));
                if (i < keys.size() - 1) sb.append(',');
                sb.append('\n');
            }
            sb.append(pad(indent)).append('}');
            return sb.toString();
        }
        return v.toString();
    }

    static String canonical(Object v) {
        if (v == null) return "null";
        if (v instanceof Boolean || v instanceof Long) return v.toString();
        if (v instanceof Double) return fmtDouble((Double) v);
        if (v instanceof String) return quote((String) v);
        if (v instanceof List) {
            List<?> list = (List<?>) v;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(',');
                sb.append(canonical(list.get(i)));
            }
            return sb.append(']').toString();
        }
        if (v instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> map = (Map<String, Object>) v;
            List<String> keys = new ArrayList<>(map.keySet());
            Collections.sort(keys);
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (String k : keys) {
