                while (len + 2 >= cap) cap *= 2;
                buf = (char *)realloc(buf, cap);
            }
            buf[len++] = c;
            p->pos++;
        }
    }
    if (p->pos >= p->len) { p->error = 1; free(buf); return NULL; }
    p->pos++; /* skip closing quote */
    buf[len] = '\0';
    return buf;
}

static json_value *parse_string(parser *p) {
    char *s = parse_string_raw(p);
    if (!s) return NULL;
    json_value *v = json_new(JSON_STRING);
    v->str_val = s;
    return v;
}

static json_value *parse_number(parser *p) {
    int start = p->pos;
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if ((c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E')
            p->pos++;
        else break;
    }
    int len = p->pos - start;
    char *raw = (char *)malloc(len + 1);
    memcpy(raw, p->s + start, len);
    raw[len] = '\0';
    double val = strtod(raw, NULL);
    json_value *v = json_new(JSON_NUMBER);
    v->num_val = val;
    v->num_raw = raw;
    return v;
}

static json_value *parse_array(parser *p) {
    p->pos++; /* skip '[' */
    json_value *v = json_new(JSON_ARRAY);
    skip_ws(p);
    if (p->pos < p->len && p->s[p->pos] == ']') {
        p->pos++;
        return v;
    }
    while (1) {
        skip_ws(p);
        json_value *item = parse_value(p);
        if (!item) { p->error = 1; json_free(v); return NULL; }
        array_push(v, item);
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->s[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            p->error = 1;
            json_free(v);
            return NULL;
        }
    }
    return v;
}

static json_value *parse_object(parser *p) {
    p->pos++; /* skip '{' */
    json_value *v = json_new(JSON_OBJECT);
    skip_ws(p);
    if (p->pos < p->len && p->s[p->pos] == '}') {
        p->pos++;
        return v;
    }
    while (1) {
        skip_ws(p);
        if (p->pos >= p->len || p->s[p->pos] != '"') { p->error = 1; json_free(v); return NULL; }
        char *key = parse_string_raw(p);
        if (!key) { p->error = 1; json_free(v); return NULL; }
        skip_ws(p);
        if (p->pos >= p->len || p->s[p->pos] != ':') { free(key); p->error = 1; json_free(v); return NULL; }
        p->pos++;
        skip_ws(p);
        json_value *val = parse_value(p);
        if (!val) { free(key); p->error = 1; json_free(v); return NULL; }
        object_add(v, key, val);
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->s[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            p->error = 1;
            json_free(v);
            return NULL;
        }
    }
    return v;
}

static json_value *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) { p->error = 1; return NULL; }
    char c = p->s[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') return parse_string(p);
    if (c == 't') {
        if (p->pos + 3 < p->len && strncmp(p->s + p->pos, "true", 4) == 0) {
            p->pos += 4;
            json_value *v = json_new(JSON_BOOL);
            v->bool_val = 1;
            return v;
        }
        p->error = 1; return NULL;
    }
    if (c == 'f') {
        if (p->pos + 4 < p->len && strncmp(p->s + p->pos, "false", 5) == 0) {
            p->pos += 5;
            json_value *v = json_new(JSON_BOOL);
            v->bool_val = 0;
            return v;
        }
        p->error = 1; return NULL;
    }
    if (c == 'n') {
        if (p->pos + 3 < p->len && strncmp(p->s + p->pos, "null", 4) == 0) {
            p->pos += 4;
            return json_new(JSON_NULL);
        }
        p->error = 1; return NULL;
    }
    if (c == '-' || (c >= '0' && c <= '9')) return parse_number(p);
    p->error = 1;
    return NULL;
}

static json_value *json_parse(const char *text, size_t len) {
    parser p = { text, 0, (int)len, 0 };
    json_value *v = parse_value(&p);
    if (p.error) { json_free(v); return NULL; }
    return v;
}

/* Deep equality */
static int json_equals(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->num_val == b->num_val;
        case JSON_STRING: return a->str_val && b->str_val && strcmp(a->str_val, b->str_val) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++)
                if (!json_equals(a->items[i], b->items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->key_count != b->key_count) return 0;
            for (int i = 0; i < a->key_count; i++) {
                int found = 0;
                for (int j = 0; j < b->key_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equals(a->vals[i], b->vals[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

/* Check if item exists in array */
static int array_contains(json_value *arr, json_value *item) {
    for (int i = 0; i < arr->item_count; i++)
        if (json_equals(arr->items[i], item)) return 1;
    return 0;
}

/* Deep copy */
static json_value *json_clone(const json_value *v) {
    json_value *c = json_new(v->type);
    c->bool_val = v->bool_val;
    c->num_val = v->num_val;
    if (v->num_raw) { c->num_raw = (char *)malloc(strlen(v->num_raw) + 1); strcpy(c->num_raw, v->num_raw); }
    if (v->str_val) { c->str_val = (char *)malloc(strlen(v->str_val) + 1); strcpy(c->str_val, v->str_val); }
    if (v->type == JSON_ARRAY) {
        c->item_cap = v->item_count;
        if (v->item_count > 0) {
            c->items = (json_value **)malloc(v->item_count * sizeof(json_value *));
            for (int i = 0; i < v->item_count; i++)
                c->items[i] = json_clone(v->items[i]);
        }
        c->item_count = v->item_count;
    }
    if (v->type == JSON_OBJECT) {
        c->key_cap = v->key_count;
        if (v->key_count > 0) {
            c->keys = (char **)malloc(v->key_count * sizeof(char *));
            c->vals = (json_value **)malloc(v->key_count * sizeof(json_value *));
            for (int i = 0; i < v->key_count; i++) {
                c->keys[i] = (char *)malloc(strlen(v->keys[i]) + 1);
                strcpy(c->keys[i], v->keys[i]);
                c->vals[i] = json_clone(v->vals[i]);
            }
        }
        c->key_count = v->key_count;
    }
    return c;
}

/* Merge: result is a new json_value */
static json_value *json_merge(const json_value *a, const json_value *b) {
    /* Both objects: merge recursively */
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new(JSON_OBJECT);
        /* Start with all of A's keys */
        for (int i = 0; i < a->key_count; i++) {
            char *k = (char *)malloc(strlen(a->keys[i]) + 1);
            strcpy(k, a->keys[i]);
            result->key_cap = 0;
            object_add(result, k, json_clone(a->vals[i]));
        }
        /* For each key in B, check if it exists in A */
        for (int i = 0; i < b->key_count; i++) {
            int found = -1;
            for (int j = 0; j < result->key_count; j++) {
                if (strcmp(result->keys[j], b->keys[i]) == 0) { found = j; break; }
            }
            if (found >= 0) {
                /* Merge recursively */
                json_value *merged = json_merge(result->vals[found], b->vals[i]);
                json_free(result->vals[found]);
                result->vals[found] = merged;
            } else {
                char *k = (char *)malloc(strlen(b->keys[i]) + 1);
                strcpy(k, b->keys[i]);
                object_add(result, k, json_clone(b->vals[i]));
            }
        }
        return result;
    }
    /* Both arrays: concatenate, dedup (A first, then new from B) */
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new(JSON_ARRAY);
        for (int i = 0; i < a->item_count; i++)
            array_push(result, json_clone(a->items[i]));
        for (int i = 0; i < b->item_count; i++) {
            if (!array_contains(result, b->items[i]))
                array_push(result, json_clone(b->items[i]));
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return json_clone(b);
}

/* Sort object keys */
typedef struct {
    char *key;
    json_value *val;
} kv_pair;

static int kv_compare(const void *a, const void *b) {
    const kv_pair *pa = (const kv_pair *)a;
    const kv_pair *pb = (const kv_pair *)b;
    return strcmp(pa->key, pb->key);
}

static void sort_object(json_value *obj) {
    if (obj->type != JSON_OBJECT || obj->key_count <= 1) {
        /* Still need to sort children if array of objects */
        if (obj->type == JSON_ARRAY) {
            for (int i = 0; i < obj->item_count; i++)
                sort_object(obj->items[i]);
        }
        return;
    }
    /* Sort keys */
    kv_pair *pairs = (kv_pair *)malloc(obj->key_count * sizeof(kv_pair));
    for (int i = 0; i < obj->key_count; i++) {
        pairs[i].key = obj->keys[i];
        pairs[i].val = obj->vals[i];
    }
    qsort(pairs, obj->key_count, sizeof(kv_pair), kv_compare);
    for (int i = 0; i < obj->key_count; i++) {
        obj->keys[i] = pairs[i].key;
        obj->vals[i] = pairs[i].val;
    }
    free(pairs);
    /* Recurse into values */
    for (int i = 0; i < obj->key_count; i++)
        sort_object(obj->vals[i]);
    if (obj->type == JSON_ARRAY) {
        for (int i = 0; i < obj->item_count; i++)
            sort_object(obj->items[i]);
    }
}

