static void sort_value(json_value *v) {
    if (!v) return;
    if (v->type == JSON_OBJECT) {
        if (v->key_count > 1) {
            kv_pair *pairs = (kv_pair *)malloc(v->key_count * sizeof(kv_pair));
            for (int i = 0; i < v->key_count; i++) {
                pairs[i].key = v->keys[i];
                pairs[i].val = v->vals[i];
            }
            qsort(pairs, v->key_count, sizeof(kv_pair), kv_compare);
            for (int i = 0; i < v->key_count; i++) {
                v->keys[i] = pairs[i].key;
                v->vals[i] = pairs[i].val;
            }
            free(pairs);
        }
        for (int i = 0; i < v->key_count; i++)
