    } else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->item_count; i++)
            sort_value(v->items[i]);
    }
}

/* Pretty print */
static void print_string_escaped(const char *s, FILE *f) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (c < 0x20) fprintf(f, "\\u%04x", c);
                else fputc(c, f);
                break;
        }
    }
    fputc('"', f);
}

static void print_number(const json_value *v, FILE *f) {
    if (v->num_raw) {
        fprintf(f, "%s", v->num_raw);
    } else {
        /* Fallback: check if integer */
        if (v->num_val == (long long)v->num_val && fabs(v->num_val) < 1e15)
            fprintf(f, "%lld", (long long)v->num_val);
        else
            fprintf(f, "%.17g", v->num_val);
    }
}

static void print_value(const json_value *v, int indent, FILE *f) {
    int i, j;
    switch (v->type) {
        case JSON_NULL:
            fprintf(f, "null");
            break;
        case JSON_BOOL:
            fprintf(f, "%s", v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(v, f);
            break;
        case JSON_STRING:
            print_string_escaped(v->str_val, f);
            break;
        case JSON_ARRAY:
            if (v->item_count == 0) {
                fprintf(f, "[]");
                break;
            }
            fprintf(f, "[\n");
            for (i = 0; i < v->item_count; i++) {
                for (j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                print_value(v->items[i], indent + 1, f);
                if (i < v->item_count - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (j = 0; j < indent * 2; j++) fputc(' ', f);
            fprintf(f, "]");
            break;
        case JSON_OBJECT:
            if (v->key_count == 0) {
                fprintf(f, "{}");
                break;
            }
            fprintf(f, "{\n");
            for (i = 0; i < v->key_count; i++) {
                for (j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                print_string_escaped(v->keys[i], f);
                fprintf(f, ": ");
                print_value(v->vals[i], indent + 1, f);
                if (i < v->key_count - 1) fputc(',', f);
                fputc('\n', f);
            }
            for (j = 0; j < indent * 2; j++) fputc(' ', f);
            fprintf(f, "}");
            break;
    }
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return NULL; }
    char *buf = (char *)malloc(sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, sz, f);
    fclose(f);
    buf[rd] = '\0';
    *out_len = rd;
    return buf;
}

