} KV;

typedef struct {
    KV *items;
    int count;
    int cap;
} KVArray;

static void kv_array_init(KVArray *a) {
    a->items = NULL;
    a->count = 0;
    a->cap = 0;
}

static int kv_array_find(KVArray *a, const char *key) {
    for (int i = 0; i < a->count; i++) {
        if (strcmp(a->items[i].key, key) == 0) return i;
    }
    return -1;
}

static void kv_array_add(KVArray *a, const char *key, int inc) {
    int idx = kv_array_find(a, key);
    if (idx >= 0) {
        a->items[idx].count += inc;
    } else {
        if (a->count >= a->cap) {
            a->cap = a->cap ? a->cap * 2 : 128;
            a->items = (KV *)realloc(a->items, (size_t)a->cap * sizeof(KV));
        }
        a->items[a->count].key = strdup(key);
        a->items[a->count].count = inc;
        a->count++;
    }
}

