    const char *path = "<tmp>";
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s\n", path);
        return 1;
    }

    KVArray levels;
    kv_array_init(&levels);

    KVArray err_components;
    kv_array_init(&err_components);

    StrArray err_messages;
    str_array_init(&err_messages);

    int hour_counts[24] = {0};
    int total_entries = 0;

    size_t line_cap = 4096;
    char *line = (char *)malloc(line_cap);
    if (!line) return 1;

    while (1) {
        size_t len = 0;
        int c;
        /* read one line */
        while ((c = fgetc(fp)) != EOF) {
            if (len + 2 >= line_cap) {
                line_cap *= 2;
                line = (char *)realloc(line, line_cap);
            }
            if (c == '\n') break;
            line[len++] = (char)c;
        }
        if (len == 0 && c == EOF) break;
        line[len] = '\0';

        /* skip empty lines */
        if (len == 0) continue;

        /* Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message */
        if (line[0] != '[') continue;

        /* find closing ] */
        char *close_bracket = strchr(line, ']');
        if (!close_bracket) continue;

        /* hour is at index 12-13: [YYYY-MM-DD HH:MM:SS] */
        int hour = 0;
        if (len >= 21) {
            hour = (line[12] - '0') * 10 + (line[13] - '0');
        }
        if (hour >= 0 && hour < 24) hour_counts[hour]++;

        /* after ] there should be a space then LEVEL */
        char *p = close_bracket + 1;
        if (*p == ' ') p++;
        else if (*p == '\0') continue;

