        char *level_start = p;
        while (*p && *p != ' ' && *p != '(') p++;
        char *level_end = p;
        *level_end = '\0';
        char *level = level_start;

        kv_array_add(&levels, level, 1);
        total_entries++;

        /* after LEVEL, expect space then (component) */
        if (*p == ' ') p++;
        if (*p != '(') continue;
        p++; /* skip ( */
        char *comp_start = p;
        while (*p && *p != ')') p++;
        if (*p == ')') *p = '\0';
        char *component = comp_start;

        /* after ) expect " - " then message */
        if (*p == ')') p++;
        if (p[0] == ' ' && p[1] == '-' && p[2] == ' ') {
            p += 3;
        } else {
            /* try just " -" */
            if (p[0] == ' ' && p[1] == '-') {
                p += 2;
                if (*p == ' ') p++;
            }
        }
        char *message = p;

        if (strcmp(level, "ERROR") == 0) {
            kv_array_add(&err_components, component, 1);

            /* check if message already exists */
            int found = 0;
            for (int i = 0; i < err_messages.count; i++) {
                if (strcmp(err_messages.items[i], message) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                str_array_add(&err_messages, message);
            }
        }
    }

    free(line);
    fclose(fp);

    /* Sort levels alphabetically */
    qsort(levels.items, (size_t)levels.count, sizeof(KV), cmp_kv_key);

    /* Sort error messages alphabetically */
    qsort(err_messages.items, (size_t)err_messages.count, sizeof(char *), cmp_str);

    /* Find component with most errors */
    int best_comp_idx = -1;
    int best_comp_count = 0;
    for (int i = 0; i < err_components.count; i++) {
        if (err_components.items[i].count > best_comp_count) {
            best_comp_count = err_components.items[i].count;
            best_comp_idx = i;
        }
    }

    /* Find busiest hour */
    int best_hour = 0;
    int best_hour_count = 0;
    for (int h = 0; h < 24; h++) {
        if (hour_counts[h] > best_hour_count) {
            best_hour_count = hour_counts[h];
            best_hour = h;
        }
    }

    /* Output */
    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < levels.count; i++) {
        printf("  %s: %d\n", levels.items[i].key, levels.items[i].count);
    }
    printf("\n");
    if (best_comp_idx >= 0) {
        printf("Component with Most Errors: %s (%d errors)\n",
               err_components.items[best_comp_idx].key, best_comp_count);
    } else {
        printf("Component with Most Errors: N/A (0 errors)\n");
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < err_messages.count; i++) {
        printf("  - %s\n", err_messages.items[i]);
