    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", best_hour, best_hour_count);

    /* Cleanup */
    kv_array_free(&levels);
    kv_array_free(&err_components);
    str_array_free(&err_messages);

    return 0;
}
