    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r' ||
                       s[len - 1] == ' '  || s[len - 1] == '\t')) {
        s[--len] = '\0';
    }
}

static char *run_command(const char *cmd) {
    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) return NULL;
    buf[0] = '\0';

    FILE *fp = popen(cmd, "r");
    if (!fp) {
        free(buf);
        return NULL;
    }

    size_t total = 0;
    for (;;) {
        if (cap - total < 2) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) {
                free(buf);
                pclose(fp);
                return NULL;
