            Some('t') => { self.pos += 4; Json::Bool(true) }
            Some('f') => { self.pos += 5; Json::Bool(false) }
            Some('n') => { self.pos += 4; Json::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut entries = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(entries);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse();
            entries.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}}' in object"),
            }
        }
        Json::Object(entries)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(items);
        }
        loop {
            let item = self.parse();
            items.push(item);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{8}'),
                        Some('f') => s.push('\u{c}'),
                        Some('u') => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let c = self.next().unwrap();
                                code = code * 16 + c.to_digit(16).unwrap();
                            }
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => panic!("Invalid escape sequence"),
                    }
                }
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        self.skip_whitespace();
        let start = self.pos;
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        Json::Number(s.parse::<f64>().unwrap())
    }
}

struct MinHeapItem {
    dist: f64,
    node: String,
}

impl Ord for MinHeapItem {
    fn cmp(&self, other: &Self) -> Ordering {
        other.dist.partial_cmp(&self.dist).unwrap()
    }
}

impl PartialOrd for MinHeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Eq for MinHeapItem {}

impl PartialEq for MinHeapItem {
    fn eq(&self, other: &Self) -> bool {
        self.dist == other.dist
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");
    let mut parser = JsonParser::new(&content);
    let json = parser.parse();

    let nodes_json = json.get("nodes").expect("Missing 'nodes'");
    let edges_json = json.get("edges").expect("Missing 'edges'");

    let nodes = nodes_json.as_array().expect("'nodes' not an array");
    let edges = edges_json.as_array().expect("'edges' not an array");

    let node_list: Vec<String> = nodes.iter()
        .map(|n| n.as_str().unwrap().to_string())
        .collect();

    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for n in &node_list {
        adj.entry(n.clone()).or_insert(Vec::new());
    }

    for e in edges {
        let from = e.get("from").unwrap().as_str().unwrap().to_string();
        let to = e.get("to").unwrap().as_str().unwrap().to_string();
        let weight = e.get("weight").unwrap().as_f64().unwrap();

        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), weight));
        adj.entry(to).or_insert_with(Vec::new).push((from, weight));
    }

    let start = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    let mut visited: HashMap<String, bool> = HashMap::new();
    for n in &node_list {
        dist.insert(n.clone(), f64::INFINITY);
        visited.insert(n.clone(), false);
    }
    dist.insert(start.clone(), 0.0);

    let mut heap: BinaryHeap<MinHeapItem> = BinaryHeap::new();
    heap.push(MinHeapItem { dist: 0.0, node: start.clone() });

    while let Some(MinHeapItem { dist: d, node }) = heap.pop() {
        if visited.get(&node).copied().unwrap_or(false) {
            continue;
        }
        visited.insert(node.clone(), true);

        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, weight) in neighbors {
                let new_dist = d + weight;
                if new_dist < dist.get(neighbor).copied().unwrap_or(f64::INFINITY) {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(MinHeapItem { dist: new_dist, node: neighbor.clone() });
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes = node_list.clone();
    sorted_nodes.sort();

    for n in &sorted_nodes {
        let d = dist.get(n).copied().unwrap_or(f64::INFINITY);
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", n);
        } else if d.fract() == 0.0 {
            println!("A -> {}: {}", n, d as i64);
        } else {
            println!("A -> {}: {}", n, d);
        }
    }
}
