use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn count_lines(data: &[u8]) -> u64 {
    if data.is_empty() {
        return 0;
    }
    let mut count = data.iter().filter(|&&b| b == b'\n').count() as u64;
    if data[data.len() - 1] != b'\n' {
        count += 1;
    }
    count
}

fn walk(root: &Path, current: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(current) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(root, &path, files);
        } else if path.is_file() {
            let rel = path.strip_prefix(root).unwrap_or(&path);
            let rel_str = rel.to_string_lossy().replace('\\', "/");

            let mut contents = Vec::new();
            if let Ok(mut f) = fs::File::open(&path) {
                let _ = f.read_to_end(&mut contents);
            }

            let chars = contents.len() as u64;
            let lines = count_lines(&contents);

            files.push((rel_str, lines, chars));
        }
    }
}

fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    for (rel_path, lines, chars) in &files {
        let p = Path::new(rel_path);
        let ext = p.extension()
            .map(|e| format!(".{}", e))
            .unwrap_or_else(|| String::new());
        groups.entry(ext).or_default().push((rel_path.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len() as u64;
        let n_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let n_chars: u64 = file_list.iter().map(|f| f.2).sum();

        println!("Extension: {}", ext);
        println!("  Files: {}", n_files);
        println!("  Total Lines: {}", n_lines);
        println!("  Total Characters: {}", n_chars);
        for (rel_path, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
        }

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

