import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class FileInfo {
        String relPath;
        long lines;
        long chars;
        FileInfo(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<FileInfo>> extMap = new TreeMap<>();
        Set<Path> visited = new HashSet<>();

        walk(root, root, extMap, visited);

        for (List<FileInfo> files : extMap.values()) {
            files.sort(Comparator.comparing(f -> f.relPath));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileInfo>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> files = entry.getValue();

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");

            long extLines = 0;
            long extChars = 0;
            for (FileInfo fi : files) {
                extLines += fi.lines;
                extChars += fi.chars;
            }

            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (FileInfo fi : files) {
                sb.append("    ").append(fi.relPath).append(": ")
                  .append(fi.lines).append(" lines, ")
                  .append(fi.chars).append(" chars\n");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ")
          .append(totalLines).append(" lines, ")
          .append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static void walk(Path dir, Path root, Map<String, List<FileInfo>> extMap, Set<Path> visited) throws IOException {
        Path realDir;
        try {
            realDir = dir.toRealPath();
        } catch (IOException e) {
            return;
        }
        if (!visited.add(realDir)) return;

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            List<Path> entries = new ArrayList<>();
            for (Path p : stream) {
                entries.add(p);
            }
            entries.sort(Comparator.comparing(p -> p.getFileName().toString()));

            for (Path filePath : entries) {
                if (Files.isSymbolicLink(filePath)) {
                    continue;
                }
                if (Files.isDirectory(filePath)) {
                    walk(filePath, root, extMap, visited);
                } else if (Files.isRegularFile(filePath)) {
                    byte[] content = Files.readAllBytes(filePath);
                    long chars = content.length;
                    long lines = countLines(content);

                    String relPath = root.relativize(filePath).toString().replace('\\', '/');

                    String fileName = filePath.getFileName().toString();
                    String ext = "";
                    int lastDot = fileName.lastIndexOf('.');
                    if (lastDot > 0) {
                        ext = fileName.substring(lastDot);
                    }

                    extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, chars));
                }
            }
        }
    }

    static long countLines(byte[] content) {
        if (content.length == 0) return 0;
        long nlCount = 0;
        for (byte b : content) {
            if (b == '\n') nlCount++;
        }
        if (content[content.length - 1] != '\n') {
            nlCount++;
        }
        return nlCount;
    }
}

