        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            List<Path> entries = new ArrayList<>();
            for (Path p : stream) {
                entries.add(p);
            }
            entries.sort(Comparator.comparing(p -> p.getFileName().toString()));

            for (Path filePath : entries) {
                if (Files.isSymbolicLink(filePath)) {
                    continue;
                }
                if (Files.isDirectory(filePath)) {
                    walk(filePath, root, extMap, visited);
                } else if (Files.isRegularFile(filePath)) {
                    byte[] content = Files.readAllBytes(filePath);
                    long chars = content.length;
                    long lines = countLines(content);

                    String relPath = root.relativize(filePath).toString().replace('\\', '/');

                    String fileName = filePath.getFileName().toString();
                    String ext = "";
                    int lastDot = fileName.lastIndexOf('.');
                    if (lastDot > 0) {
                        ext = fileName.substring(lastDot);
                    }

                    extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, chars));
                }
            }
        }
    }

    static long countLines(byte[] content) {
        if (content.length == 0) return 0;
        long nlCount = 0;
        for (byte b : content) {
            if (b == '\n') nlCount++;
        }
        if (content[content.length - 1] != '\n') {
            nlCount++;
        }
        return nlCount;
    }
}
