import Foundation

let baseDir = "<tmp>"
let fileManager = FileManager.default

struct FileStats {
    let relativePath: String
    let lines: Int
    let chars: Int
    let ext: String
}

var allFiles: [FileStats] = []

func walkDirectory(path: String) {
    let dirURL = URL(fileURLWithPath: path)
    let keys: [URLResourceKey] = [.isSymbolicLinkKey, .isDirectoryKey]
    guard let contents = try? fileManager.contentsOfDirectory(at: dirURL, includingPropertiesForKeys: keys, options: []) else {
        return
    }
    for item in contents {
        let values = try? item.resourceValues(forKeys: Set(keys))
        let isSymlink = values?.isSymbolicLink ?? false
        let isDir = values?.isDirectory ?? false
        if isSymlink {
            continue
        }
        if isDir {
            walkDirectory(path: item.path)
        } else {
            let relPath = item.path.replacingOccurrences(of: baseDir + "/", with: "")
            guard let data = try? Data(contentsOf: item) else {
                continue
            }
            let chars = data.count
            var lineCount: Int
            if data.isEmpty {
                lineCount = 0
            } else {
                let nlCount = data.reduce(0) { $0 + ($1 == 10 ? 1 : 0) }
                if data.last == 10 {
                    lineCount = nlCount
                } else {
                    lineCount = nlCount + 1
                }
            }
            let ext = item.pathExtension
            allFiles.append(FileStats(relativePath: relPath, lines: lineCount, chars: chars, ext: ext))
        }
    }
}

walkDirectory(path: baseDir)

var groups: [String: [FileStats]] = [:]
for file in allFiles {
    let key = file.ext.isEmpty ? "(none)" : "." + file.ext
    groups[key, default: []].append(file)
}

let sortedExts = groups.keys.sorted()

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

for ext in sortedExts {
    let files = groups[ext]!
    let sortedFiles = files.sorted { $0.relativePath < $1.relativePath }
    let extTotalLines = sortedFiles.reduce(0) { $0 + $1.lines }
    let extTotalChars = sortedFiles.reduce(0) { $0 + $1.chars }
    print("Extension: \(ext)")
    print("  Files: \(sortedFiles.count)")
    print("  Total Lines: \(extTotalLines)")
    print("  Total Characters: \(extTotalChars)")
    for f in sortedFiles {
        print("    \(f.relativePath): \(f.lines) lines, \(f.chars) chars")
    }
    totalFiles += sortedFiles.count
    totalLines += extTotalLines
    totalChars += extTotalChars
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

