    for (int i = 0; i < n; i++) {
        Adj *a = adj[i];
        while (a) { Adj *nx = a->next; free(a); a = nx; }
    }
    free(adj);
    free(dist);
    free(visited);
    free(order);
    for (int i = 0; i < n; i++) free(names[i]);
