    p->pos++;
    int start = p->pos;
    while (p->pos < p->len && p->s[p->pos] != '"') {
        if (p->s[p->pos] == '\\' && p->pos + 1 < p->len) p->pos++;
        p->pos++;
    }
    int len = p->pos - start;
    char *r = malloc(len + 1);
    memcpy(r, p->s + start, len);
    r[len] = '\0';
    if (p->pos < p->len) p->pos++;
    return r;
}

double parse_json_number(P *p) {
    skip_ws(p);
    char *end;
    double v = strtod(p->s + p->pos, &end);
    p->pos = (int)(end - p->s);
    return v;
}

void skip_json_value(P *p) {
    skip_ws(p);
    if (p->pos >= p->len) return;
    char c = p->s[p->pos];
    if (c == '"') {
        parse_json_string(p);
    } else if (c == '[') {
        p->pos++;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; return; }
        while (p->pos < p->len) {
            skip_json_value(p);
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; }
            else if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; break; }
            else break;
        }
    } else if (c == '{') {
        p->pos++;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; return; }
        while (p->pos < p->len) {
            skip_ws(p);
            if (p->pos >= p->len || p->s[p->pos] != '"') break;
            char *key = parse_json_string(p);
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ':') p->pos++;
            skip_json_value(p);
            free(key);
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; }
            else if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; break; }
            else break;
        }
    } else if (c == '-' || (c >= '0' && c <= '9')) {
        parse_json_number(p);
    } else {
        while (p->pos < p->len && p->s[p->pos] != ',' && p->s[p->pos] != '}' &&
               p->s[p->pos] != ']' && p->s[p->pos] != ' ' && p->s[p->pos] != '\n' &&
               p->s[p->pos] != '\r' && p->s[p->pos] != '\t')
            p->pos++;
    }
}

int find_key(const char *json, const char *key, int jlen) {
    char *pat = malloc(jlen + 3);
    pat[0] = '"';
    memcpy(pat + 1, key, jlen);
    pat[jlen + 1] = '"';
    pat[jlen + 2] = '\0';
    char *found = strstr(json, pat);
    free(pat);
    if (!found) return -1;
    int pos = (int)(found - json) + jlen + 2;
    int total = (int)strlen(json);
    while (pos < total && json[pos] != ':') pos++;
    if (pos >= total) return -1;
    return pos + 1;
}

typedef struct Adj {
    int to;
    double w;
    struct Adj *next;
} Adj;

int main(void) {
    const char *path = "<tmp>";

    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", path);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *json = malloc(fsize + 1);
    size_t rd = fread(json, 1, fsize, f);
    json[rd] = '\0';
    fclose(f);

    P p = { json, 0, (int)fsize };

    /* Parse nodes */
    int nodes_pos = find_key(json, "nodes", 5);
    if (nodes_pos < 0) { fprintf(stderr, "Error: 'nodes' not found\n"); return 1; }
    p.pos = nodes_pos;
    skip_ws(&p);
    if (p.pos >= p.len || p.s[p.pos] != '[') { fprintf(stderr, "Error: expected [ after nodes\n"); return 1; }
    p.pos++;

    int ncap = 64, ncount = 0;
    char **names = malloc(ncap * sizeof(char *));

    skip_ws(&p);
    if (p.pos < p.len && p.s[p.pos] == ']') {
        p.pos++;
    } else {
        while (p.pos < p.len) {
            skip_ws(&p);
            if (p.pos >= p.len) break;
            if (p.s[p.pos] == ']') { p.pos++; break; }
            if (p.s[p.pos] != '"') break;
            char *name = parse_json_string(&p);
            if (!name) break;
            if (ncount >= ncap) { ncap *= 2; names = realloc(names, ncap * sizeof(char *)); }
            names[ncount++] = name;
            skip_ws(&p);
            if (p.pos < p.len && p.s[p.pos] == ',') { p.pos++; }
            else if (p.pos < p.len && p.s[p.pos] == ']') { p.pos++; break; }
            else break;
        }
    }
    int n = ncount;

    /* Parse edges */
    int edges_pos = find_key(json, "edges", 5);
    if (edges_pos < 0) { fprintf(stderr, "Error: 'edges' not found\n"); return 1; }
    p.pos = edges_pos;
    skip_ws(&p);
    if (p.pos >= p.len || p.s[p.pos] != '[') { fprintf(stderr, "Error: expected [ after edges\n"); return 1; }
    p.pos++;

    typedef struct { int from, to; double weight; } E;
    int ecap = 64, ecount = 0;
    E *edges = malloc(ecap * sizeof(E));

    skip_ws(&p);
    if (p.pos < p.len && p.s[p.pos] == ']') {
        p.pos++;
    } else {
        while (p.pos < p.len) {
            skip_ws(&p);
            if (p.pos >= p.len) break;
            if (p.s[p.pos] == ']') { p.pos++; break; }
            if (p.s[p.pos] != '{') break;
            p.pos++;

            E e = { -1, -1, 0.0 };
            skip_ws(&p);
            if (p.pos < p.len && p.s[p.pos] == '}') {
                p.pos++;
            } else {
                while (p.pos < p.len) {
                    skip_ws(&p);
                    if (p.pos >= p.len || p.s[p.pos] != '"') break;
                    char *key = parse_json_string(&p);
                    if (!key) break;
                    skip_ws(&p);
                    if (p.pos < p.len && p.s[p.pos] == ':') p.pos++;

                    if (strcmp(key, "from") == 0) {
                        char *val = parse_json_string(&p);
                        for (int i = 0; i < n; i++) {
                            if (strcmp(names[i], val) == 0) { e.from = i; break; }
                        }
                        free(val);
                    } else if (strcmp(key, "to") == 0) {
                        char *val = parse_json_string(&p);
                        for (int i = 0; i < n; i++) {
                            if (strcmp(names[i], val) == 0) { e.to = i; break; }
                        }
                        free(val);
                    } else if (strcmp(key, "weight") == 0) {
                        e.weight = parse_json_number(&p);
                    } else {
                        skip_json_value(&p);
                    }
                    free(key);

                    skip_ws(&p);
                    if (p.pos < p.len && p.s[p.pos] == ',') { p.pos++; }
                    else if (p.pos < p.len && p.s[p.pos] == '}') { p.pos++; break; }
                    else break;
                }
            }

            if (ecount >= ecap) { ecap *= 2; edges = realloc(edges, ecap * sizeof(E)); }
            edges[ecount++] = e;

            skip_ws(&p);
            if (p.pos < p.len && p.s[p.pos] == ',') { p.pos++; }
            else if (p.pos < p.len && p.s[p.pos] == ']') { p.pos++; break; }
            else break;
        }
    }
    int m = ecount;

    /* Build adjacency list (undirected) */
    Adj **adj = calloc(n, sizeof(Adj *));
    for (int i = 0; i < m; i++) {
        int u = edges[i].from, v = edges[i].to;
        double w = edges[i].weight;
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        Adj *a = malloc(sizeof(Adj));
        a->to = v; a->w = w; a->next = adj[u]; adj[u] = a;
        Adj *b = malloc(sizeof(Adj));
        b->to = u; b->w = w; b->next = adj[v]; adj[v] = b;
    }

    /* Find source node "A" */
    int src = -1;
    for (int i = 0; i < n; i++) {
        if (strcmp(names[i], "A") == 0) { src = i; break; }
    }
    if (src < 0) { fprintf(stderr, "Error: node 'A' not found\n"); return 1; }

    /* Dijkstra's algorithm */
    const double INF = 1e18;
    double *dist = malloc(n * sizeof(double));
    int *visited = calloc(n, sizeof(int));
    for (int i = 0; i < n; i++) dist[i] = INF;
    dist[src] = 0.0;

    for (int iter = 0; iter < n; iter++) {
        int u = -1;
        double min_d = INF;
        for (int i = 0; i < n; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u < 0) break;
        visited[u] = 1;
        for (Adj *a = adj[u]; a; a = a->next) {
            if (!visited[a->to] && dist[u] + a->w < dist[a->to]) {
                dist[a->to] = dist[u] + a->w;
            }
        }
    }

    /* Sort node indices alphabetically */
    int *order = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) order[i] = i;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (strcmp(names[order[j]], names[order[j + 1]]) > 0) {
                int tmp = order[j]; order[j] = order[j + 1]; order[j + 1] = tmp;
            }
        }
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < n; i++) {
        int idx = order[i];
        if (dist[idx] >= INF / 2) {
            printf("A -> %s: unreachable\n", names[idx]);
        } else if (fabs(dist[idx] - (double)(long long)dist[idx]) < 1e-9) {
            printf("A -> %s: %lld\n", names[idx], (long long)dist[idx]);
        } else {
            printf("A -> %s: %g\n", names[idx], dist[idx]);
        }
    }

    /* Cleanup */
    for (int i = 0; i < n; i++) {
        Adj *a = adj[i];
        while (a) { Adj *nx = a->next; free(a); a = nx; }
    }
    free(adj);
    free(dist);
    free(visited);
    free(order);
    for (int i = 0; i < n; i++) free(names[i]);
    free(names);
    free(edges);
    free(json);

    return 0;
}
